type Option func(*Config)

func WithTimeout(d time.Duration) Option { return func(c *Config) { c.timeout = d } }

func NewClient(addr string, opts ...Option) (*Client, error) {
    c := &Config{addr: addr, timeout: 30 * time.Second, retries: 3} // defaults
    for _, o := range opts { o(c) }                                 // then options
    return newClient(c)                                             // then validate
}
// NewClient("db:5432", WithTimeout(5*time.Second))

